    {
      "type": "checkbox",
      "id": "motion",
      "label": "Enable button hover motion",
      "default": true
    },
    {
      "type": "range",
      "id": "speed",
      "label": "Hover speed",
      "min": 50,
      "max": 200,
      "step": 10,
      "unit": "%",
      "default": 100
    }
  ],
  "blocks": [
    {
      "type": "typography",
      "name": "Typography controls",
      "limit": 1,
      "settings": [
        {
          "type": "header",
          "content": "Heading"
        },
        {
          "type": "font_picker",
          "id": "heading_font",
          "label": "Font family",
          "default": "poppins_n4"
        },
        {
          "type": "range",
          "id": "heading_weight",
          "label": "Thickness",
          "min": 100,
          "max": 900,
          "step": 100,
          "default": 900
        },
        {
          "type": "range",
          "id": "heading_size",
          "label": "Desktop size",
          "min": 10,
          "max": 100,
          "step": 1,
          "unit": "px",
          "default": 52
        },
        {
          "type": "range",
          "id": "heading_mobile",
          "label": "Mobile size",
          "min": 10,
          "max": 80,
          "step": 1,
          "unit": "px",
          "default": 34
        },
        {
          "type": "range",
          "id": "heading_tracking",
          "label": "Letter spacing",
          "min": -6,
          "max": 20,
          "step": 1,
          "unit": "%",
          "default": -2
        },
        {
          "type": "range",
          "id": "heading_leading",
          "label": "Line height",
          "min": 90,
          "max": 200,
          "step": 5,
          "unit": "%",
          "default": 105
        },
        {
          "type": "header",
          "content": "Year numeral"
        },
        {
          "type": "font_picker",
          "id": "year_font",
          "label": "Font family",
          "default": "poppins_n4"
        },
        {
          "type": "range",
          "id": "year_weight",
          "label": "Thickness",
          "min": 100,
          "max": 900,
          "step": 100,
          "default": 900
        },
        {
          "type": "range",
          "id": "year_size",
          "label": "Desktop size",
          "min": 10,
          "max": 200,
          "step": 2,
          "unit": "px",
          "default": 150
        },
        {
          "type": "range",
          "id": "year_mobile",
          "label": "Mobile size",
          "min": 10,
          "max": 80,
          "step": 1,
          "unit": "px",
          "default": 60
        },
        {
          "type": "range",
          "id": "year_tracking",
          "label": "Letter spacing",
          "min": -6,
          "max": 20,
          "step": 1,
          "unit": "%",
          "default": -5
        },
        {
          "type": "range",
          "id": "year_leading",
          "label": "Line height",
          "min": 90,
